  // '.hb-cta' is in this selector because the pill lives OUTSIDE the drawer:\n    // tapping it while the drawer is open must still close the drawer.\n    rail.querySelectorAll('.hb-nav a, .hb-cta').forEach(function (a) {\n      a.addEventListener('click', function () { setOpen(false); });\n    });\n    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') setOpen(false); });\n  })();\n</script> <main id=\"main\"> <section class=\"kc-arrive\" data-astro-cid-6kyx63kz><div class=\"wrap\" data-astro-cid-6kyx63kz><div class=\"kc-grid\" data-astro-cid-6kyx63kz><div class=\"kc-copy\" data-astro-cid-6kyx63kz><span class=\"kick kc-kick\" data-field=\"hero.kicker\" data-astro-cid-6kyx63kz>Coffee in Marikina</span><h1 class=\"kc-h1\" data-field=\"hero.headline\" data-astro-cid-6kyx63kz>A good cup, <em>a little pause.</em></h1><p class=\"lede kc-lede\" data-field=\"hero.sub\" data-astro-cid-6kyx63kz>Drop in for a coffee, find a quiet seat or take a cup along for the rest of your day.</p><div class=\"kc-ctas\" data-astro-cid-6kyx63kz><a class=\"btn btn--fill\" href=\"#location\" data-field=\"hero.cta1.text\" data-href-field=\"hero.cta1.href\" data-astro-cid-6kyx63kz>Find a seat</a><a class=\"btn btn--line kc-cta-line\" href=\"#menu\" data-field=\"hero.cta2.text\" data-href-field=\"hero.cta2.href\" data-astro-cid-6kyx63kz>See the menu</a></div><div class=\"kc-tags\" data-astro-cid-6kyx63kz><span class=\"chip\" data-field=\"hero.meta1\" data-astro-cid-6kyx63kz>Coffee and small bites</span><span class=\"chip\" data-field=\"hero.meta2\" data-astro-cid-6kyx63kz>Dine in or takeaway</span><span class=\"chip\" data-field=\"hero.trustLine\" data-astro-cid-6kyx63kz>Ask about the daily bake</span></div></div><div class=\"plate kc-shot\" data-astro-cid-6kyx63kz><div class=\"ph kc-ph\" data-image-field=\"hero.image\" style=\"background-image:url('/capture-previews/photos/cafe-sample-v1.webp');\" role=\"img\" aria-label=\"Haplos Coffee\" data-astro-cid-6kyx63kz></div></div></div></div></section> <section class=\"kc-proof\" data-astro-cid-wppd6gkw><div class=\"wrap\" data-astro-cid-wppd6gkw><div class=\"kc-proof-slab band-dark\" style=\"--cols:3\" data-astro-cid-wppd6gkw><div class=\"kc-proof-cell reveal\" data-delay=\"0\" data-astro-cid-wppd6gkw><div class=\"fig kc-proof-fig\" data-field=\"trust.cells.0.num\" data-astro-cid-wppd6gkw>8 am</div><div class=\"mono kc-proof-lab\" data-field=\"trust.cells.0.label\" data-astro-cid-wppd6gkw>Doors open</div></div><div class=\"kc-proof-cell reveal\" data-delay=\"1\" data-astro-cid-wppd6gkw><div class=\"fig kc-proof-fig\" data-field=\"trust.cells.1.num\" data-astro-cid-wppd6gkw>Hot / iced</div><div class=\"mono kc-proof-lab\" data-field=\"trust.cells.1.label\" data-astro-cid-wppd6gkw>Your everyday cup</div></div><div class=\"kc-proof-cell reveal\" data-delay=\"2\" data-astro-cid-wppd6gkw><div class=\"fig kc-proof-fig\" data-field=\"trust.cells.2.num\" data-astro-cid-wppd6gkw>Takeaway</div><div class=\"mono kc-proof-lab\" data-field=\"trust.cells.2.label\" data-astro-cid-wppd6gkw>Or stay a little longer</div></div></div></div></section> <section class=\"story\" id=\"about\" data-astro-cid-qwo6hfg4><div class=\"wrap\" data-astro-cid-qwo6hfg4><div class=\"story-grid\" data-astro-cid-qwo6hfg4><div class=\"plate story-plate reveal\" data-astro-cid-qwo6hfg4><div class=\"ph\" data-image-field=\"about.image\" role=\"img\" aria-label=\"The Haplos team\" style=\"background-image:url('/capture-previews/photos/cafe-sample-v1.webp');\" data-astro-cid-qwo6hfg4></div></div><div class=\"story-copy\" data-astro-cid-qwo6hfg4><span class=\"kick\" data-field=\"about.tag\" data-astro-cid-qwo6hfg4>A place to pause</span><h2 class=\"h2 story-h reveal\" data-field=\"about.headline\" data-astro-cid-qwo6hfg4>Make a little room for coffee.</h2><p class=\"lede story-p reveal\" data-delay=\"1\" data-field=\"about.lead\" data-astro-cid-qwo6hfg4>A neighbourhood spot for a familiar cup and an unhurried break.</p><p class=